begin;
do $$
declare users uuid[];a uuid;b uuid;c uuid;club uuid:=gen_random_uuid();msg uuid:=gen_random_uuid();event uuid:=gen_random_uuid();code text;raw jsonb;denied boolean;
begin
 select array_agg(id) into users from(select id from auth.users order by created_at limit 3)x;a:=users[1];b:=users[2];c:=users[3];
 perform set_config('request.jwt.claims',jsonb_build_object('sub',a,'role','authenticated')::text,true);execute 'set local role authenticated';
 raw:=public.club_action('create',null,jsonb_build_object('id',club,'name','Rollback notification QA','is_open',false));code:=raw->>'invite_code';
 assert raw->>'notification_mode'='invitations';
 perform set_config('request.jwt.claims',jsonb_build_object('sub',b,'role','authenticated')::text,true);
 perform public.club_action('join_code',null,jsonb_build_object('code',code));
 execute 'reset role';update public.rider_club_members set joined_at=now()-interval '1 day',last_read_at=now()-interval '1 day' where club_id=club and user_id=b;execute 'set local role authenticated';
 perform set_config('request.jwt.claims',jsonb_build_object('sub',a,'role','authenticated')::text,true);
 perform public.club_action('message',club,jsonb_build_object('id',msg,'body','temporary notification test'));
 execute 'reset role';assert (select count(*) from public.club_push_outbox where club_id=club)=0,'invitation mode suppresses plain messages';execute 'set local role authenticated';
 perform set_config('request.jwt.claims',jsonb_build_object('sub',b,'role','authenticated')::text,true);
 raw:=public.club_action('snapshot',club);assert (raw->>'unread_count')::int=1;
 raw:=public.club_action('read',club);assert (raw->>'unread_count')::int=0;
 perform public.club_action('notifications',club,jsonb_build_object('mode','all','user_id',a));
 perform set_config('request.jwt.claims',jsonb_build_object('sub',a,'role','authenticated')::text,true);
 perform public.club_action('message',club,jsonb_build_object('id',gen_random_uuid(),'body','all-mode message'));
 perform public.club_action('event_create',club,jsonb_build_object('id',event,'title','Temporary event','starts_at',now()+interval '1 day'));
 execute 'reset role';assert (select count(*) from public.club_push_outbox where club_id=club and recipient_id=b)=2;
 assert (select notification_mode from public.rider_club_members where club_id=club and user_id=a)='invitations','cannot change other member preferences';execute 'set local role authenticated';
 perform set_config('request.jwt.claims',jsonb_build_object('sub',b,'role','authenticated')::text,true);
 perform public.club_action('notifications',club,jsonb_build_object('mode','off'));
 denied:=false;begin perform count(*) from public.club_push_outbox;exception when insufficient_privilege then denied:=true;end;assert denied;
 denied:=false;begin perform public.register_club_push_device('not-a-registered-token');exception when others then denied:=sqlerrm like '%DEVICE_UNAVAILABLE%';end;assert denied;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',a,'role','authenticated')::text,true);
 perform public.club_action('event_cancel',club,jsonb_build_object('id',event));
 perform public.club_action('message',club,jsonb_build_object('id',gen_random_uuid(),'body','off-mode message'));
 execute 'reset role';assert (select count(*) from public.club_push_outbox where club_id=club)=2,'off suppresses all kinds';execute 'set local role authenticated';
 perform set_config('request.jwt.claims',jsonb_build_object('sub',c,'role','authenticated')::text,true);
 denied:=false;begin perform public.club_action('notifications',club,jsonb_build_object('mode','all'));exception when others then denied:=sqlerrm like '%CLUB_MEMBER_REQUIRED%';end;assert denied;
 execute 'reset role';
 assert not has_function_privilege('anon','public.claim_club_push(uuid)','execute');
 assert not has_function_privilege('authenticated','public.claim_club_push(uuid)','execute');
 assert has_function_privilege('service_role','public.claim_club_push(uuid)','execute');
 assert not has_function_privilege('authenticated','app_private.club_action_base(text,uuid,jsonb)','execute');
end $$;
rollback;
select 'Club notification modes, private preferences, unread/read markers, outbox permissions and UI token ownership passed; rolled back, no notifications sent' result;
